rows=list(csv.DictReader(open('players_invented_names.csv')))
fields=list(rows[0].keys())
for role,s in N.items():
    names=[x for x in s.split('|')]
    grp=sorted([r for r in rows if r['role']==role],key=lambda r:-int(r['rating']))
    assert len(names)>=len(grp),(role,len(names),len(grp))
    for r,n in zip(grp,names): r['name']=n
assert len({r['name'] for r in rows})==300
rows.sort(key=lambda r:-int(r['rating']))
w=csv.DictWriter(open('players.csv','w',newline=''),fieldnames=fields); w.writeheader(); w.writerows(rows)
for r in rows[:8]: print(r['name'],r['role'],r['rating'])
